def parse_lg_waveform(waveform_raw: str):
    """Parse a binary string representing a low gain waveform"""
    w = bitstring.ConstBitStream(bin=waveform_raw)
    ints = []
    while w.pos < len(w):
        w.read('bits:8')  # skip 2
        ints += w.readlist(['uint:12']*2)
    return ints


